export const CLIMATE_ACTION_ACTIVITIES = [
{n:1,type:"mcq",micro:"Cuaca vs iklim",q:"Perbedaan cuaca & iklim adalah...",options:["cuaca adalah keadaan udara hari ini di suatu tempat; iklim adalah pola cuaca rata-rata selama bertahun-tahun","keduanya sama persis, hanya berbeda nama saja, sehingga boleh dipakai bergantian untuk semua keadaan","iklim hanya ada di daerah dingin sedangkan daerah tropis tidak memiliki iklim"],answer:0,explain:"Satu hari yang dingin adalah cuaca; kecenderungan suhu naik selama puluhan tahun adalah perubahan iklim.",hint:"Hari ini vs pola bertahun-tahun."},
{n:2,type:"mcq",micro:"Efek rumah kaca",q:"Efek rumah kaca alami berguna karena...",options:["tidak ada gunanya bagi bumi karena gas di atmosfer hanya membuat udara pengap","gas tertentu di atmosfer menahan sebagian panas matahari sehingga bumi cukup hangat untuk kehidupan","membuat bumi semakin dingin setiap tahun karena gas di atmosfer memantulkan semua panas matahari ke luar angkasa"],answer:1,explain:"Tanpa efek rumah kaca alami, bumi akan terlalu dingin; masalahnya muncul ketika efek ini menguat berlebihan.",hint:"Menahan panas agar bumi hangat."},
{n:3,type:"mcq",micro:"Penyebab utama pemanasan",q:"Penyebab utama menguatnya efek rumah kaca sejak zaman industri adalah...",options:["letusan gunung berapi yang melepaskan banyak gas ke udara","perubahan jarak bumi ke matahari yang membuat bumi menerima lebih banyak panas dari matahari dalam setiap tahun","pembakaran batu bara, minyak, & gas, serta penggundulan hutan oleh manusia"],answer:2,explain:"Aktivitas manusia menambahkan gas rumah kaca, terutama karbon dioksida, jauh lebih cepat daripada alam bisa menyerapnya.",hint:"Bakar fosil + tebang hutan."},
{n:4,type:"mcq",micro:"Gas rumah kaca utama",q:"Gas rumah kaca yang paling banyak ditambahkan manusia adalah...",options:["karbon dioksida (CO2), terutama dari pembakaran bahan bakar fosil","oksigen yang dilepaskan tumbuhan saat berfotosintesis","uap air dari laut yang naik ke atmosfer dan membentuk awan"],answer:0,explain:"Selain CO2, ada juga metana & lainnya, tetapi CO2 dari fosil adalah penyumbang terbesar.",hint:"CO2 dari bahan bakar fosil."},
{n:5,type:"mcq",micro:"Arti pemanasan global",q:"'Pemanasan global' berarti...",options:["hanya musim panas di beberapa tempat yang menjadi lebih lama","suhu rata-rata permukaan bumi meningkat dalam jangka panjang","setiap tempat di bumi menjadi panas pada setiap hari tanpa kecuali dan tanpa ada hari yang sejuk"],answer:1,explain:"Kenaikan rata-rata beberapa derajat saja sudah cukup mengubah pola cuaca & ekosistem secara luas.",hint:"Suhu rata-rata bumi naik."},
{n:6,type:"tf",micro:"Tanda perubahan iklim",q:"Benar atau Salah: Gelombang panas, cuaca ekstrem, naiknya permukaan laut, & mencairnya es kutub tidak ada hubungannya dengan perubahan iklim.",answer:false,explain:"Sebaliknya, pola-pola ini justru tanda perubahan iklim yang dicatat para ilmuwan di seluruh dunia secara konsisten selama beberapa dekade.",hint:"Panas ekstrem, laut naik, es mencair = tanda iklim."},
{n:7,type:"mcq",micro:"Dampak di Indonesia",q:"Contoh dampak perubahan iklim yang dirasakan di Indonesia:",options:["tidak ada dampak di Indonesia karena perubahan iklim hanya terjadi di negara lain","hanya salju yang semakin bertambah banyak di pegunungan & dataran rendah di seluruh wilayah Indonesia","banjir & kekeringan yang makin ekstrem, panas menyengat, & ancaman bagi wilayah pesisir"],answer:2,explain:"Sebagai negara kepulauan tropis, Indonesia rentan pada kenaikan laut, cuaca ekstrem, & gangguan pertanian.",hint:"Banjir, kekeringan, panas, pesisir."},
{n:8,type:"mcq",micro:"Hutan & karbon",q:"Hutan berperan penting bagi iklim karena...",options:["pohon menyerap & menyimpan karbon dioksida saat tumbuh","pohon justru menghasilkan karbon dioksida dalam jumlah besar","hutan tidak berpengaruh apa pun pada iklim karena pohon hanya berfungsi sebagai tempat tinggal hewan"],answer:0,explain:"Menebang & membakar hutan melepaskan karbon tersimpan & menghilangkan penyerap alami.",hint:"Pohon menyerap & menyimpan karbon."},
{n:9,type:"mcq",micro:"Mitigasi vs adaptasi",q:"'Mitigasi' iklim berarti mengurangi penyebabnya, sedangkan 'adaptasi' berarti...",options:["menambah emisi lebih cepat supaya orang mau berubah","menyesuaikan diri agar tahan terhadap dampak yang sudah & akan terjadi","mengabaikan masalahnya sambil berharap keadaan akan membaik dengan sendirinya tanpa perlu berbuat apa-apa"],answer:1,explain:"Contoh adaptasi: sistem peringatan banjir, tanaman tahan kekeringan, bangunan tahan panas.",hint:"Menyesuaikan diri dengan dampak."},
{n:10,type:"mcq",micro:"Satu hari dingin",q:"Satu hari yang tidak biasa dinginnya di suatu kota...",options:["membuktikan pemanasan global tidak nyata & hanya karangan ilmuwan","berarti iklim dunia sudah membaik dan kita tidak perlu lagi mengkhawatirkan tentang suhu bumi di masa depan","adalah cuaca, & tidak membantah tren pemanasan jangka panjang secara global"],answer:2,explain:"Iklim dinilai dari rata-rata jangka panjang & skala global, bukan satu peristiwa lokal.",hint:"Satu hari = cuaca, bukan iklim."},
{n:11,type:"tf",micro:"Aksi masih berarti",q:"Benar atau Salah: Meski sebagian dampak perubahan iklim sudah terjadi, mengurangi emisi sekarang tetap sangat berarti untuk membatasi kerusakan lebih lanjut.",answer:true,explain:"Setiap pengurangan emisi menurunkan risiko dampak terburuk; ini bukan situasi 'semua atau tidak sama sekali'.",hint:"Setiap pengurangan tetap berarti."},
{n:12,type:"mcq",micro:"Jejak karbon",q:"'Jejak karbon' seseorang atau kegiatan adalah...",options:["perkiraan jumlah gas rumah kaca yang dihasilkan dari kegiatan itu","jejak kaki yang tertinggal di tanah berlumpur","jumlah pohon yang sudah ditanam oleh seseorang dalam satu tahun untuk menyerap karbon dari udara"],answer:0,explain:"Menghitungnya membantu melihat kegiatan mana yang paling besar dampaknya.",hint:"Perkiraan gas rumah kaca yang dihasilkan."},
{n:13,type:"tf",micro:"Energi & transport penyumbang besar",q:"Benar atau Salah: Di tingkat dunia, pembangkitan energi & transportasi hampir tidak menyumbang emisi gas rumah kaca.",answer:false,explain:"Sebaliknya, keduanya termasuk penyumbang emisi terbesar, sehingga beralih ke energi bersih & transportasi rendah emisi adalah pengungkit besar.",hint:"Energi & transportasi = penyumbang besar."},
{n:14,type:"mcq",micro:"Konsensus ilmiah",q:"Tentang penyebab perubahan iklim saat ini, para ilmuwan iklim di dunia...",options:["sepakat bahwa perubahan iklim sekarang murni siklus alami yang tidak dipengaruhi manusia","sangat sepakat bahwa aktivitas manusia adalah penyebab utamanya","terbagi rata setengah-setengah antara yang percaya dan menyangkal"],answer:1,explain:"Ada tingkat kesepakatan ilmiah yang sangat tinggi, berdasarkan banyak jenis bukti yang saling menguatkan.",hint:"Sangat sepakat: sebab utamanya manusia."},
{n:15,type:"open",micro:"Perubahan yang kamu amati",q:"Tanyakan pada orang tua atau kakek-nenekmu tentang cuaca atau musim saat mereka kecil. Tuliskan satu perbedaan yang mereka sebut & bagaimana perasaanmu mendengarnya.",explain:"Mendengar pengalaman lintas generasi membuat perubahan iklim terasa nyata & dekat.",hint:"Satu perbedaan yang disebut + perasaanmu.",sample:"Nenekku bercerita dulu musim hujan & kemarau lebih mudah ditebak, & banjir besar jarang terjadi di kampungnya. Sekarang hujan sering datang sangat deras dalam waktu singkat lalu lama kering. Aku jadi sadar perubahan ini bukan hal jauh, tapi sudah dialami keluargaku sendiri, & itu membuatku ingin ikut berbuat sesuatu."},
{n:16,type:"mcq",micro:"Aksi individu: energi",q:"Tindakan pribadi yang membantu mengurangi emisi:",options:["menyalakan semua alat listrik sepanjang waktu supaya rumah terang & terasa ramai oleh bunyi","tidak peduli dari mana listrik berasal asalkan tagihan bulanan di rumah tetap bisa dibayar tepat waktu","menghemat listrik & mendukung keluarga beralih ke alat & sumber energi yang lebih efisien"],answer:2,explain:"Konsumsi energi rumah tangga adalah salah satu bagian jejak karbon yang bisa kita pengaruhi.",hint:"Hemat listrik + energi efisien."},
{n:17,type:"tf",micro:"Bukan soal kesempurnaan",q:"Benar atau Salah: Ikut menghadapi perubahan iklim tidak menuntut hidup 'nol emisi' yang sempurna; banyak orang melakukan perubahan yang tidak sempurna tetapi konsisten lebih berdampak.",answer:true,explain:"Tekanan menjadi sempurna sering membuat orang menyerah; perbaikan bertahap oleh banyak orang lebih kuat.",hint:"Konsisten & tidak sempurna tetap berdampak."},
{n:18,type:"mcq",micro:"Aksi individu: transportasi",q:"Pilihan transportasi yang lebih rendah emisi untuk jarak yang memungkinkan:",options:["berjalan kaki, bersepeda, berbagi kendaraan, atau naik transportasi umum","naik kendaraan pribadi sendirian ke mana pun pergi, bahkan untuk perjalanan dekat","naik kendaraan bermotor pribadi walaupun hanya untuk menempuh jarak yang sangat dekat dari rumah"],answer:0,explain:"Transportasi adalah bagian jejak karbon yang bisa banyak dikurangi dengan pilihan sehari-hari.",hint:"Jalan, sepeda, berbagi, transportasi umum."},
{n:19,type:"order",micro:"Dari khawatir ke aksi",q:"Urutkan langkah mengubah kekhawatiran soal iklim menjadi tindakan:",items:["Pelajari fakta dari sumber tepercaya agar paham, bukan panik","Pilih satu atau dua bidang yang bisa kamu pengaruhi (energi, transportasi, konsumsi)","Ambil langkah nyata & ajak orang di sekitarmu","Ikut suara bersama: sekolah, komunitas, atau kegiatan lingkungan"],answer:[0,1,2,3],explain:"Pahami, fokus pada yang bisa kamu ubah, bertindak, lalu bergabung dengan aksi bersama.",hint:"Pahami dulu, aksi bersama terakhir."},
{n:20,type:"mcq",micro:"Ringkasan",q:"Inti menghadapi perubahan iklim adalah...",options:["menganggap masalah ini terlalu besar sehingga tidak ada satu pun hal yang bisa dilakukan manusia biasa","mengurangi penyebab (emisi) & menyesuaikan diri dengan dampak, lewat tindakan pribadi sekaligus perubahan sistem","menunggu teknologi ajaib datang suatu hari nanti untuk menyelesaikan semuanya tanpa perlu usaha kita"],answer:1,explain:"Mitigasi + adaptasi, individu + sistem: keduanya diperlukan bersamaan.",hint:"Kurangi penyebab + adaptasi; pribadi + sistem."},
{n:21,type:"classify",micro:"Mitigasi atau adaptasi",q:"Kelompokkan setiap tindakan:",items:["Beralih ke pembangkit listrik tenaga surya","Membangun tanggul & sistem peringatan dini banjir","Menanam pohon di lahan gundul","Menanam padi varietas tahan kekeringan"],groups:["Mitigasi (mengurangi penyebab)","Adaptasi (menghadapi dampak)"],answer:{"Mitigasi (mengurangi penyebab)":["Beralih ke pembangkit listrik tenaga surya","Menanam pohon di lahan gundul"],"Adaptasi (menghadapi dampak)":["Membangun tanggul & sistem peringatan dini banjir","Menanam padi varietas tahan kekeringan"]},explain:"Mitigasi menekan emisi & memperkuat penyerap karbon; adaptasi mengurangi kerugian dari dampak yang sudah tak terhindarkan.",hint:"Mengurangi penyebab vs menghadapi akibat."},
{n:22,type:"mcq",micro:"Aksi individu: makanan",q:"Pilihan makanan yang umumnya berjejak karbon lebih rendah:",options:["makan daging merah dalam jumlah banyak pada setiap kali makan agar tubuh kuat & sehat","membuang makanan yang tidak habis tanpa dipikirkan lagi karena sisa makanan akan terurai dengan sendirinya","lebih banyak sayur, biji-bijian, & sumber protein nabati, serta mengurangi makanan terbuang"],answer:2,explain:"Produksi sebagian pangan hewani, terutama daging merah, & makanan yang terbuang menyumbang emisi cukup besar.",hint:"Lebih nabati + kurangi makanan terbuang."},
{n:23,type:"mcq",micro:"Konsumsi barang",q:"Membeli lebih sedikit, memilih yang tahan lama, & memperbaiki barang membantu iklim karena...",options:["memproduksi & mengangkut barang baru menghasilkan emisi; memakai lebih lama mengurangi kebutuhan itu","tidak ada hubungannya dengan iklim karena emisi hanya berasal dari kendaraan dan pabrik besar","membeli lebih banyak barang justru menurunkan emisi karena pabrik bekerja lebih efisien ketika pesanan banyak"],answer:0,explain:"Setiap barang membawa 'emisi tersembunyi' dari pembuatan & pengirimannya.",hint:"Barang baru = emisi produksi & pengiriman."},
{n:24,type:"tf",micro:"Individu & sistem sama perlu",q:"Benar atau Salah: Menghadapi perubahan iklim butuh perubahan kebiasaan individu sekaligus perubahan besar pada sistem energi, transportasi, & industri yang ditentukan pemerintah & perusahaan.",answer:true,explain:"Tindakan pribadi penting & membangun dukungan, tetapi pengungkit terbesar ada pada kebijakan & sistem.",hint:"Individu + sistem, keduanya."},
{n:25,type:"mcq",micro:"Pohon sebagai solusi",q:"Menanam & melindungi pohon membantu iklim, tetapi...",options:["pohon tidak berpengaruh apa-apa pada iklim sehingga menanamnya hanya membuang tenaga dan waktu saja","tidak bisa menggantikan pengurangan pembakaran bahan bakar fosil; keduanya perlu","cukup dengan menanam pohon saja sehingga emisi boleh terus naik"],answer:1,explain:"Pohon menyerap sebagian karbon, tetapi jumlah emisi fosil terlalu besar untuk 'ditutup' hanya dengan menanam.",hint:"Pohon membantu, tapi bukan pengganti kurangi fosil."},
{n:26,type:"mcq",micro:"Keadilan iklim",q:"'Keadilan iklim' menyoroti kenyataan bahwa...",options:["setiap orang terkena dampak yang sama persis, tidak peduli seberapa banyak emisi yang ia hasilkan","hanya negara-negara kaya yang dirugikan oleh perubahan iklim sedangkan negara miskin tidak terkena dampaknya","kelompok & negara yang paling sedikit menyebabkan emisi sering paling parah terkena dampaknya"],answer:2,explain:"Masyarakat miskin & negara berkembang, termasuk banyak wilayah di Indonesia, sering paling rentan meski kontribusi emisinya kecil.",hint:"Paling sedikit menyebabkan, paling parah terkena."},
{n:27,type:"mcq",micro:"Menghadapi rasa cemas iklim",q:"Bila kamu merasa cemas atau sedih memikirkan iklim, cara sehat menanganinya:",options:["akui perasaan itu, bicarakan dengan orang tepercaya, & salurkan menjadi tindakan bersama orang lain","memendamnya sendirian dalam hati sampai perasaan itu menumpuk dan membuatmu merasa kewalahan","memaksa diri berhenti peduli supaya tidak sedih lagi dan tidak perlu memikirkannya"],answer:0,explain:"Perasaan cemas soal iklim wajar; berbagi & bertindak bersama membuatnya lebih ringan & bermakna.",hint:"Akui, bicarakan, salurkan jadi aksi bersama."},
{n:28,type:"tf",micro:"Doom bukan satu-satunya cerita",q:"Benar atau Salah: Meski tantangannya besar, sudah ada banyak solusi iklim yang berjalan (energi terbarukan makin murah, kota lebih hijau, hutan dilindungi), sehingga menyerah bukan satu-satunya sikap.",answer:true,explain:"Melihat kemajuan yang nyata membantu kita tetap punya harapan sekaligus terus mendorong lebih banyak aksi.",hint:"Solusi nyata sudah berjalan."},
{n:29,type:"mcq",micro:"Lingkaran umpan balik",q:"Contoh 'lingkaran umpan balik' yang memperparah pemanasan:",options:["angin kencang yang menghentikan pemanasan dengan cara meniup panas keluar dari bumi dalam sekejap","es kutub yang mencair mengurangi pemantulan sinar matahari, sehingga bumi menyerap lebih banyak panas","hujan lebat yang mendinginkan bumi secara permanen sehingga pemanasan global tidak mungkin terjadi lagi"],answer:1,explain:"Beberapa perubahan bisa saling memperkuat, itulah kenapa membatasi pemanasan sedini mungkin penting.",hint:"Es mencair -> panas lebih terserap -> makin panas."},
{n:30,type:"mcq",micro:"Aksi: bersuara",q:"Salah satu tindakan iklim paling berdampak yang bisa dilakukan pelajar:",options:["menyimpan kepedulianmu sebagai rahasia pribadi supaya tidak ada teman yang menganggapmu aneh","menganggap urusan iklim hanyalah urusan orang dewasa saja sehingga pelajar tidak perlu ikut berbicara","membicarakannya, mengajak keluarga & teman peduli, & mendukung kebijakan lingkungan yang baik"],answer:2,explain:"Perubahan sosial & politik dimulai dari percakapan; suara banyak orang mendorong perubahan sistem.",hint:"Bicarakan, ajak, dukung kebijakan baik."},
{n:31,type:"mcq",micro:"Terapan: ke sekolah",q:"Untuk perjalanan harian ke sekolah yang tidak terlalu jauh, pilihan rendah emisi:",options:["jalan kaki, sepeda, antar-jemput bersama, atau angkutan umum","diantar mobil sendiri setiap hari untuk jarak 500 meter","tidak berangkat sekolah"],answer:0,explain:"Perjalanan rutin yang diubah menjadi lebih hemat emisi berdampak besar karena dilakukan setiap hari.",hint:"Jalan, sepeda, bareng, angkutan umum."},
{n:32,type:"tf",micro:"Makanan terbuang & iklim",q:"Benar atau Salah: Makanan yang terbuang tidak menyumbang emisi apa pun karena toh tidak jadi dimakan.",answer:false,explain:"Sebaliknya, makanan terbuang tetap menyumbang emisi karena energi, air, & lahan sudah dipakai memproduksinya, ditambah gas dari pembusukannya. Mengurangi makanan terbuang adalah aksi iklim yang mudah di rumah.",hint:"Sudah dipakai sumber daya + gas pembusukan."},
{n:33,type:"mcq",micro:"Terapan: kebun sekolah",q:"Kebun & penghijauan sekolah membantu iklim & pembelajaran dengan cara...",options:["menghabiskan banyak air tanpa guna sehingga lebih baik lahan sekolah dibiarkan kosong saja","menyerap sedikit karbon, menyejukkan lingkungan, & menjadi sarana belajar langsung tentang alam","tidak ada manfaatnya bagi iklim maupun pelajaran karena pohon cepat mati di sekolah"],answer:1,explain:"Ruang hijau sekolah adalah aksi kecil sekaligus laboratorium hidup.",hint:"Serap karbon + sejuk + belajar."},
{n:34,type:"mcq",micro:"Terapan: mendukung pilihan keluarga",q:"Keluargamu mempertimbangkan memasang panel surya atau membeli sepeda listrik. Peranmu sebagai anak:",options:["menganggap itu bukan urusanmu karena keputusan membeli barang sepenuhnya hak orang dewasa di rumah","menolak semua perubahan itu karena menurutmu merepotkan dan lebih enak memakai cara yang lama","cari informasi manfaat & biayanya, sampaikan dengan antusias, & bantu menjalankannya"],answer:2,explain:"Anak bisa menjadi pendorong perubahan positif di rumah dengan informasi & semangat.",hint:"Bantu cari info + dorong + jalankan."},
{n:35,type:"mcq",micro:"Terapan: barang elektronik",q:"Memakai HP atau laptop lebih lama sebelum menggantinya membantu iklim karena...",options:["produksi perangkat elektronik menghasilkan emisi besar; memperpanjang pemakaian mengurangi kebutuhan produksi baru","perangkat lama memakai sedikit listrik sehingga lebih baik terus dipakai sampai benar-benar rusak","tidak ada hubungannya dengan iklim sebab emisi hanya berasal dari pembangkit listrik dan kendaraan"],answer:0,explain:"Sebagian besar 'emisi' sebuah gawai berasal dari pembuatannya, bukan pemakaian hariannya.",hint:"Emisi terbesar ada di produksinya."},
{n:36,type:"order",micro:"Merancang aksi iklim kelas",q:"Urutkan langkah kelas merancang satu aksi iklim nyata:",items:["Pelajari & pilih satu masalah yang bisa kalian pengaruhi (mis. sampah, energi, penghijauan)","Tetapkan tujuan yang jelas & terukur","Bagi peran & jalankan aksinya","Ukur hasilnya & bagikan agar menginspirasi kelas lain"],answer:[0,1,2,3],explain:"Pilih fokus, tetapkan tujuan, jalankan, lalu ukur & bagikan.",hint:"Pilih fokus dulu, bagikan hasil terakhir."},
{n:37,type:"mcq",micro:"Terapan: liburan keluarga",q:"Saat keluarga merencanakan liburan, pilihan yang lebih ramah iklim bila memungkinkan:",options:["tidak berlibur sepanjang tahun supaya keluarga tidak menghasilkan emisi","memilih tujuan yang lebih dekat atau moda perjalanan darat bersama daripada penerbangan jauh yang sering","memilih penerbangan terjauh setiap tahun supaya liburan terasa istimewa dan berkesan bagi seluruh keluarga"],answer:1,explain:"Penerbangan jarak jauh berjejak karbon tinggi; ini salah satu keputusan besar keluarga yang berdampak.",hint:"Lebih dekat / darat bersama bila bisa."},
{n:38,type:"open",micro:"Aksi pilihanmu",q:"Pilih satu bidang (energi, transportasi, makanan, konsumsi, penghijauan, atau bersuara). Tulis satu aksi nyata yang akan kamu lakukan bulan ini & bagaimana kamu akan mengajak satu orang lain ikut.",explain:"Aksi yang spesifik & melibatkan orang lain lebih mungkin bertahan & menyebar.",hint:"Satu aksi nyata + cara mengajak satu orang.",sample:"Bidang: transportasi. Aksi: aku akan bersepeda atau jalan kaki ke sekolah minimal tiga hari seminggu, bukan minta diantar untuk jarak yang sebenarnya dekat. Mengajak orang lain: aku akan mengajak teman sebelah rumah berangkat bersepeda bersama supaya lebih aman & seru, sekaligus mengurangi satu perjalanan motor."},
{n:39,type:"mcq",micro:"Menolak informasi menyesatkan",q:"Saat menemukan klaim di media sosial bahwa 'perubahan iklim itu tipuan', sikap kritis:",options:["langsung membagikannya kepada semua teman karena kamu merasa informasi itu perlu cepat diketahui orang","langsung percaya begitu saja tanpa memeriksa karena banyak orang lain yang sudah ikut membagikannya","periksa apa kata lembaga sains iklim tepercaya & banyak sumber, bukan langsung percaya atau menyebarkan"],answer:2,explain:"Ada kampanye yang sengaja menabur keraguan; memeriksa sumber ilmiah membantu kita tidak tersesat.",hint:"Cek lembaga sains tepercaya & banyak sumber."},
{n:40,type:"tf",micro:"Taktik penundaan",q:"Benar atau Salah: Selain menyangkal langsung, ada juga cara halus menghambat aksi iklim, misalnya berkata 'nanti saja', 'percuma kalau bukan semua', atau 'itu salah individu, bukan sistem', untuk menunda tindakan.",answer:true,explain:"Mengenali argumen yang menunda membantu kita tetap fokus pada tindakan yang seimbang antara individu & sistem, sekarang.",hint:"Penundaan juga bentuk hambatan."},
{n:41,type:"mcq",micro:"Terapan: kampanye hemat energi sekolah",q:"Menghubungkan aksi hemat listrik sekolah dengan iklim berarti menjelaskan bahwa...",options:["listrik yang dihemat mengurangi bahan bakar fosil yang dibakar di pembangkit, sehingga menekan emisi","hemat listrik tidak ada kaitannya dengan iklim karena emisi hanya berasal dari asap kendaraan di jalan","iklim hanya dipengaruhi oleh hutan sehingga hemat listrik tidak memberi perubahan bagi bumi"],answer:0,explain:"Menghubungkan tindakan sehari-hari dengan gambaran besar membuat aksi terasa bermakna.",hint:"Hemat listrik -> kurang fosil dibakar -> kurang emisi."},
{n:42,type:"mcq",micro:"Terapan: menanam & merawat pohon",q:"Agar penanaman pohon benar-benar bermanfaat, yang penting adalah...",options:["menanam pohon di lahan yang justru merusak ekosistem lain, selama jumlah pohon yang ditanam banyak","memilih jenis yang sesuai, menanam di tempat yang tepat, & merawatnya sampai tumbuh besar","menanam sebanyak mungkin pohon dalam satu hari lalu meninggalkannya begitu saja tanpa ada yang merawat"],answer:1,explain:"Pohon yang mati muda atau salah tempat memberi sedikit manfaat; perawatan jangka panjang yang menentukan.",hint:"Jenis tepat + tempat tepat + dirawat."},
{n:43,type:"mcq",micro:"Terapan: keluarga berdebat kendaraan",q:"Di rumah ada perdebatan antara membeli mobil kedua atau memakai sepeda & transportasi umum lebih sering. Sudut pandang iklim:",options:["mobil kedua menjadi pilihan terbaik bagi iklim maupun bagi keuangan keluarga jangka panjang","pilihan transportasi tidak berpengaruh pada iklim karena emisi hanya berasal dari pabrik","mengurangi ketergantungan pada kendaraan pribadi umumnya menurunkan emisi & biaya keluarga"],answer:2,explain:"Keputusan besar keluarga seperti kendaraan berdampak bertahun-tahun pada jejak karbon.",hint:"Kurangi ketergantungan kendaraan pribadi."},
{n:44,type:"tf",micro:"Adaptasi tetap perlu",q:"Benar atau Salah: Selama kita mengurangi emisi, kita tidak perlu lagi menyiapkan diri menghadapi dampak iklim seperti banjir & panas ekstrem.",answer:false,explain:"Sebaliknya, karena sebagian pemanasan sudah terjadi, kita tetap perlu beradaptasi (peringatan dini, kota tahan banjir & panas) sambil berusaha keras mengurangi emisi.",hint:"Kurangi emisi + siapkan diri hadapi dampak."},
{n:45,type:"mcq",micro:"Terapan: teman merasa putus asa",q:"Temanmu berkata 'buat apa peduli iklim, semua sudah terlambat'. Respons yang membantu:",options:["akui perasaannya, bagikan contoh solusi yang berjalan, & ajak melakukan satu aksi kecil bersama","setuju dengan temanmu & ikut menyerah karena kamu juga merasa semuanya memang sudah terlambat","memarahi temanmu karena terlalu pesimis supaya ia segera sadar & mau ikut peduli seperti kamu"],answer:0,explain:"Harapan tumbuh dari tindakan; melakukan sesuatu bersama sering mengubah rasa tak berdaya.",hint:"Akui + tunjukkan solusi + aksi kecil bersama."},
{n:46,type:"mcq",micro:"Terapan: memilih produk",q:"Sebagai konsumen muda, cara kecil mendukung iklim:",options:["mengganti barang sesering mungkin agar memakai produk terbaru yang katanya lebih efisien","memilih barang tahan lama, mengurangi barang sekali pakai, & mendukung usaha yang jelas ramah lingkungan","membeli apa saja yang paling murah tanpa memikirkan dampaknya terhadap lingkungan maupun iklim"],answer:1,explain:"Pilihan belanja jutaan orang ikut menentukan produk & praktik apa yang berkembang.",hint:"Tahan lama + kurangi sekali pakai + dukung yang ramah."},
{n:47,type:"mcq",micro:"Terapan: hari tanpa daging",q:"Keluarga mencoba satu hari dalam seminggu tanpa daging. Ini...",options:["berbahaya bagi kesehatan bila hanya dilakukan sehari dalam seminggu karena tubuh membutuhkan daging setiap hari","tidak berdampak pada jejak karbon karena makanan tidak berhubungan dengan iklim","salah satu cara sederhana mengurangi jejak karbon pangan, sambil tetap makan bergizi"],answer:2,explain:"Mengurangi, bukan harus menghilangkan, konsumsi daging merah sudah membantu; menu nabati bisa tetap bergizi.",hint:"Kurangi daging beberapa hari, tetap bergizi."},
{n:48,type:"tf",micro:"Aksi kecil dikali banyak",q:"Benar atau Salah: Karena aksi iklim satu keluarga terasa kecil, maka meski jutaan keluarga & pemerintah ikut bertindak, hasilnya tetap tidak berarti.",answer:false,explain:"Sebaliknya, perubahan iklim adalah masalah akumulatif; solusinya juga akumulasi dari banyak tindakan di semua tingkat, sehingga jutaan aksi kecil ditambah perubahan sistem berdampak sangat besar.",hint:"Kecil dikali jutaan + sistem = besar."},
{n:49,type:"mcq",micro:"Terapan: sekolah belum bertindak",q:"Sekolahmu belum punya program lingkungan sama sekali. Langkah pelajar:",options:["ajukan usulan konkret (pilah sampah, hemat energi, penghijauan) ke guru & OSIS dengan rencana & data","mengeluh di media sosial tanpa membawa usulan kepada guru maupun pengurus OSIS","menyerah begitu saja karena merasa usulanmu tidak akan didengar oleh pihak sekolah mana pun"],answer:0,explain:"Usulan yang rapi & didukung teman lebih mungkin memulai perubahan di sekolah.",hint:"Usulkan program konkret dengan rencana."},
{n:50,type:"mcq",micro:"Terapan: memakai ulang & berbagi",q:"Bertukar buku, meminjam alat, & membeli barang bekas layak pakai membantu iklim karena...",options:["tidak berhubungan dengan iklim karena emisi hanya dari kendaraan","mengurangi jumlah barang baru yang perlu diproduksi & diangkut","menambah emisi karena barang lama harus dibuang jauh"],answer:1,explain:"Ekonomi berbagi & barang bekas menekan 'emisi tersembunyi' dari produksi.",hint:"Kurangi produksi barang baru."},
{n:51,type:"mcq",micro:"Terapan: air & iklim",q:"Menghemat air panas & energi terkait iklim karena...",options:["air menyerap karbon sehingga lebih baik dipanaskan lebih lama","tidak ada kaitannya dengan emisi karena air panas berasal dari matahari","memanaskan air biasanya memakai listrik atau gas yang menghasilkan emisi"],answer:2,explain:"Banyak aksi hemat sumber daya sekaligus merupakan aksi iklim.",hint:"Memanaskan air = energi = emisi."},
{n:52,type:"order",micro:"Menyelenggarakan penanaman pohon",q:"Urutkan langkah kegiatan penanaman pohon sekolah yang bermanfaat:",items:["Pilih lokasi & jenis pohon yang sesuai dengan bantuan pihak yang paham","Siapkan bibit, alat, & pembagian tugas","Tanam dengan cara yang benar bersama-sama","Susun jadwal penyiraman & perawatan berbulan-bulan ke depan"],answer:[0,1,2,3],explain:"Rencanakan lokasi & jenis, siapkan, tanam, lalu rawat berkelanjutan.",hint:"Rencana dulu, perawatan terakhir."},
{n:53,type:"mcq",micro:"Terapan: pesan ke pembuat kebijakan",q:"Ketika ada kesempatan menyuarakan pendapat (surat, forum anak, kegiatan sekolah), pesan iklim yang kuat berupa...",options:["permintaan konkret & beralasan, misalnya menambah jalur sepeda atau ruang hijau, bukan sekadar 'selamatkan bumi'","tuntutan yang mustahil dipenuhi dan tanpa alasan sehingga membuat orang justru enggan mendengarkanmu","ejekan kepada pejabat yang dianggap lamban supaya mereka merasa malu lalu cepat mengambil tindakan"],answer:0,explain:"Permintaan yang spesifik & masuk akal lebih mungkin ditindaklanjuti.",hint:"Permintaan konkret & beralasan."},
{n:54,type:"mcq",micro:"Terapan: bencana di daerahmu",q:"Setelah banjir atau gelombang panas melanda daerahmu, cara menghubungkannya dengan aksi iklim:",options:["menyalahkan warga lain yang dianggap paling banyak menyumbang masalah tanpa melihat penyebab yang lebih besar","bantu pemulihan sesuai kemampuan, lalu dukung upaya adaptasi (drainase, ruang hijau) & pengurangan emisi jangka panjang","menganggapnya nasib belaka yang tidak bisa diubah sehingga tidak perlu melakukan apa-apa sesudahnya"],answer:1,explain:"Peristiwa ekstrem adalah pengingat pentingnya adaptasi & mitigasi sekaligus.",hint:"Bantu pulih + dukung adaptasi + kurangi emisi."},
{n:55,type:"mcq",micro:"Terapan: konsumsi listrik gawai",q:"Kebiasaan digital yang sedikit membantu:",options:["memutar video berkualitas tertinggi sepanjang malam walau tak ada yang menonton","tidak mematikan layar perangkat supaya tak perlu menyalakannya kembali setiap kali dibutuhkan","tidak membiarkan video streaming berjalan tanpa ditonton & mengunduh sekali untuk ditonton berulang"],answer:2,explain:"Pusat data & jaringan memakai energi; kebiasaan digital yang sadar sedikit mengurangi permintaan itu.",hint:"Jangan streaming tanpa ditonton."},
{n:56,type:"open",micro:"Surat untuk masa depan",q:"Tulis pesan singkat untuk dirimu 10 tahun lagi tentang apa yang kamu harap sudah kamu lakukan untuk iklim.",explain:"Menuliskan harapan & niat membantu menjaga arah tindakan jangka panjang.",hint:"Sebut kebiasaan & peran yang kamu harapkan.",sample:"Untuk aku 10 tahun lagi: aku harap kamu tetap peduli & tidak menyerah. Aku harap kamu sudah membiasakan hidup hemat energi, lebih banyak jalan & bersepeda, memilih barang dengan bijak, & ikut kegiatan atau memilih pemimpin yang serius soal lingkungan. Aku harap kamu ikut menjaga agar adik-adik kita mewarisi bumi yang masih layak."},
{n:57,type:"mcq",micro:"Terapan: mengurangi barang sekali pakai acara",q:"Panitia acara sekolah bisa menekan emisi & sampah dengan...",options:["memakai peralatan guna ulang, menyediakan air isi ulang, & merencanakan porsi makanan agar tidak berlebih","membagikan suvenir plastik sebanyak mungkin kepada semua tamu supaya acara terlihat meriah & berkesan","menyediakan makanan jauh lebih banyak daripada jumlah peserta supaya tak ada yang kekurangan"],answer:0,explain:"Perencanaan acara yang sadar mengurangi sampah & emisi dari produksi barang serta makanan terbuang.",hint:"Guna ulang + air isi ulang + porsi pas."},
{n:58,type:"tf",micro:"Harapan itu pilihan aktif",q:"Benar atau Salah: Harapan soal iklim bukan berarti menutup mata pada masalah, melainkan memilih untuk tetap bertindak karena percaya tindakan masih bisa mengubah hasil.",answer:true,explain:"Harapan yang aktif mendorong orang terus berupaya; keputusasaan justru membuat orang berhenti.",hint:"Harapan = memilih tetap bertindak."},
{n:59,type:"mcq",micro:"Terapan: memilih hobi",q:"Contoh hobi yang ramah iklim & tetap menyenangkan:",options:["kegiatan yang membutuhkan perjalanan jauh dengan pesawat terbang setiap akhir pekan","berkebun, bersepeda, membuat kerajinan dari barang bekas, menjelajah alam sekitar","mengoleksi barang-barang baru sebanyak-banyaknya setiap bulan karena terasa menyenangkan bagi pemiliknya"],answer:1,explain:"Banyak kegiatan yang memuaskan tidak memerlukan konsumsi tinggi.",hint:"Berkebun, sepeda, kerajinan bekas, alam."},
{n:60,type:"mcq",micro:"Terapan: mengajak sekolah pakai energi bersih",q:"Ide besar seperti panel surya sekolah paling mungkin terwujud bila diajukan dengan...",options:["hanya semangat tanpa angka, rencana, atau dukungan dari pihak sekolah maupun dari teman-temanmu","paksaan kepada pihak sekolah agar segera menyetujui usulan","perkiraan biaya, penghematan tagihan bertahun-tahun, manfaat belajar, & dukungan banyak murid serta guru"],answer:2,explain:"Usulan besar butuh kasus yang meyakinkan secara biaya, manfaat, & dukungan.",hint:"Angka + manfaat + dukungan luas."},
{n:61,type:"mcq",micro:"Pengungkit terbesar",q:"Bila harus memilih beberapa perubahan berdampak paling besar terhadap emisi, biasanya di bidang...",options:["sistem energi (listrik), transportasi, & penggunaan lahan/hutan","warna cat rumah dan jenis perabot yang dipakai di dalamnya","jenis tanaman hias di kamar dan cara merawatnya setiap hari"],answer:0,explain:"Memahami di mana emisi terbesar berada membantu memfokuskan aksi pribadi & tuntutan kebijakan.",hint:"Energi, transportasi, lahan/hutan."},
{n:62,type:"mcq",micro:"Mengapa individu saja tidak cukup",q:"Aksi individu penting tetapi tidak cukup sendirian karena...",options:["sistem akan berubah dengan sendirinya tanpa dorongan dari siapa saja sehingga kita cukup menunggu","banyak pilihan rendah emisi belum tersedia atau terjangkau bagi semua orang tanpa perubahan sistem & kebijakan","individu tidak berpengaruh apa-apa sehingga tindakan pribadi tak perlu dilakukan oleh orang mana pun"],answer:1,explain:"Misalnya, sulit naik transportasi umum bila jaringannya belum ada; di sinilah kebijakan berperan.",hint:"Pilihan hijau perlu didukung sistem."},
{n:63,type:"mcq",micro:"Mengapa individu tetap penting",q:"Meski sistem yang menentukan, aksi individu tetap berarti karena...",options:["satu orang bisa menyelesaikan semuanya sendiri tanpa bantuan orang lain mana pun, jadi kebijakan tidak diperlukan","hanya untuk pamer di media sosial supaya terlihat peduli lingkungan","membangun kebiasaan, menormalkan pilihan hijau, & memperkuat dukungan bagi kebijakan yang lebih besar"],answer:2,explain:"Gerakan besar tumbuh dari banyak orang yang mengubah kebiasaan & menuntut perubahan.",hint:"Bangun kebiasaan + dukungan untuk kebijakan."},
{n:64,type:"tf",micro:"Keadilan antar generasi",q:"Benar atau Salah: Keputusan iklim yang diambil hari ini hanya berdampak pada orang dewasa sekarang & tidak memengaruhi dunia yang diwarisi anak-anak & generasi berikutnya.",answer:false,explain:"Sebaliknya, keputusan iklim hari ini sangat memengaruhi dunia generasi mendatang; itulah kenapa suara anak muda dalam isu ini penting, merekalah yang hidup paling lama dengan hasilnya.",hint:"Keputusan hari ini menentukan warisan generasi berikut."},
{n:65,type:"mcq",micro:"Titik kritis",q:"Ilmuwan memperingatkan adanya 'titik kritis' iklim, yaitu...",options:["ambang batas yang bila terlampaui, sebagian perubahan menjadi sulit atau tak bisa dibalik","hari tertentu ketika seluruh kehidupan di bumi hilang bersamaan","angka-angka dalam laporan ilmiah yang sebenarnya tidak berarti apa-apa bagi kehidupan manusia sehari-hari"],answer:0,explain:"Inilah alasan membatasi pemanasan sedini mungkin jauh lebih baik daripada menunggu.",hint:"Ambang yang sulit dibalik bila terlampaui."},
{n:66,type:"mcq",micro:"Menimbang klaim solusi",q:"Saat mendengar 'satu teknologi akan menyelesaikan semua masalah iklim', sikap bijak:",options:["menolak semua teknologi baru karena menurutmu teknologi hanya membuat masalah iklim menjadi lebih buruk lagi","menyambut inovasi, tetapi tetap mendukung pengurangan emisi sekarang karena mengandalkan satu solusi masa depan itu berisiko","berhenti melakukan apa-apa sekarang & menunggu teknologi itu muncul menyelesaikan masalah iklim"],answer:1,explain:"Solusi iklim membutuhkan banyak pendekatan sekaligus, bukan bertaruh pada satu keajaiban.",hint:"Sambut inovasi, tetap kurangi emisi sekarang."},
{n:67,type:"mcq",micro:"Emisi & ketimpangan",q:"Di dunia, jejak karbon per orang...",options:["sama untuk orang di seluruh dunia tanpa memandang negara tempat tinggal maupun penghasilannya","paling besar pada anak-anak karena mereka paling sering memakai alat elektronik dan mainan baru","sangat berbeda antar negara & antar kelompok pendapatan; sebagian kecil orang menyumbang porsi besar emisi"],answer:2,explain:"Ini bagian dari keadilan iklim: tanggung jawab & kemampuan bertindak tidak merata.",hint:"Sangat timpang antar negara & kelompok."},
{n:68,type:"tf",micro:"Bukan salah anak-anak",q:"Benar atau Salah: Perubahan iklim bukan disebabkan oleh anak-anak, tetapi anak-anak tetap bisa & berhak ikut menjadi bagian dari solusinya.",answer:true,explain:"Rasa bersalah berlebihan tidak membantu; yang membantu adalah rasa mampu untuk ikut bertindak & bersuara.",hint:"Bukan salahmu, tapi kamu boleh ikut bertindak."},
{n:69,type:"mcq",micro:"Kota yang lebih tahan iklim",q:"Ciri kota yang lebih siap menghadapi iklim:",options:["banyak ruang hijau & pepohonan, drainase baik, transportasi umum, & bangunan hemat energi","semua permukaan tanahnya tertutup beton tanpa pepohonan sehingga kota tampak rapi & mudah dibersihkan","tidak memiliki sistem peringatan bencana supaya warga tidak panik"],answer:0,explain:"Perencanaan kota yang baik sekaligus mengurangi emisi & melindungi warga dari dampak.",hint:"Hijau + drainase + transportasi umum + hemat energi."},
{n:70,type:"order",micro:"Kampanye kesadaran iklim di sekolah",q:"Urutkan langkah kampanye kesadaran iklim yang efektif:",items:["Pelajari fakta dari sumber tepercaya & siapkan pesan yang jelas serta jujur","Pilih beberapa aksi nyata yang bisa dilakukan warga sekolah","Sampaikan lewat poster, presentasi kelas, & contoh nyata dari panitia","Ukur partisipasi & rayakan kemajuan untuk menjaga semangat"],answer:[0,1,2,3],explain:"Pelajari, tentukan aksi nyata, sampaikan, lalu ukur & rayakan.",hint:"Fakta dulu, rayakan kemajuan terakhir."},
{n:71,type:"mcq",micro:"Menghindari 'greenwashing'",q:"'Greenwashing' adalah...",options:["program penghijauan resmi yang dijalankan oleh pemerintah bersama warga untuk menanam banyak pohon baru","ketika sebuah produk atau perusahaan mengaku ramah lingkungan padahal sebenarnya tidak, untuk menarik pembeli","mencuci pakaian memakai sabun ramah lingkungan supaya air limbahnya tidak mencemari sungai di sekitar rumah"],answer:1,explain:"Konsumen yang kritis memeriksa bukti klaim 'hijau', bukan sekadar percaya label & warna kemasan.",hint:"Klaim hijau palsu untuk menarik pembeli."},
{n:72,type:"mcq",micro:"Menilai aksi iklim",q:"Pertanyaan yang baik untuk menilai sebuah aksi iklim:",options:["'Apakah aksi itu terlihat keren dan bagus sekali kalau difoto lalu dibagikan di media sosial?'","'Apakah orang yang terkenal & punya banyak pengikut yang ikut melakukan aksi tersebut?'","'Apakah ia benar-benar mengurangi emisi atau melindungi dari dampak, & bisakah diperluas ke banyak orang?'"],answer:2,explain:"Aksi yang berdampak nyata & bisa ditiru banyak orang lebih berarti daripada yang sekadar simbolik.",hint:"Nyata mengurangi emisi/dampak + bisa diperluas."},
{n:73,type:"mcq",micro:"Peran hutan & lahan gambut Indonesia",q:"Melindungi hutan & lahan gambut Indonesia penting bagi iklim dunia karena...",options:["keduanya menyimpan karbon sangat besar yang akan terlepas bila rusak atau terbakar","tidak berpengaruh pada iklim karena kerusakan hutan hanya dirasakan warga sekitar","hanya penting untuk pariwisata & keindahan alam saja sedangkan iklim tidak terkait dengan keduanya"],answer:0,explain:"Kebakaran hutan & gambut melepaskan sejumlah besar karbon; menjaganya adalah kontribusi besar Indonesia.",hint:"Menyimpan karbon sangat besar."},
{n:74,type:"open",micro:"Refleksi peran",q:"Menurutmu, apa peran yang paling cocok untukmu dalam menghadapi perubahan iklim (mis. mengubah kebiasaan, mengajak orang, membuat karya, ikut kegiatan)? Jelaskan alasannya.",explain:"Setiap orang punya cara berkontribusi yang berbeda; menemukan yang cocok membuat aksi lebih berkelanjutan.",hint:"Sebut peranmu + alasan itu cocok untukmu.",sample:"Aku merasa peran yang cocok untukku adalah mengajak & menjelaskan, karena aku suka bercerita & teman-teman biasanya mau mendengarku. Aku bisa membuat poster atau video pendek tentang aksi sederhana, & mengajak kelas ikut kegiatan penghijauan. Selain itu aku tetap akan mengubah kebiasaanku sendiri supaya ajakanku jujur."},
{n:75,type:"tf",micro:"Bukan terlalu terlambat",q:"Benar atau Salah: Meski beberapa dampak iklim sudah terjadi & sebagian tidak bisa dihindari, tindakan sekarang masih menentukan apakah masa depan menjadi sulit atau jauh lebih buruk.",answer:true,explain:"Bukan pilihan antara 'aman' & 'kiamat', melainkan antara 'buruk' & 'jauh lebih buruk'; itulah kenapa setiap aksi berarti.",hint:"Aksi sekarang menentukan seberapa buruk."},
{n:76,type:"mcq",micro:"Menghargai pekerja lingkungan",q:"Terhadap petugas kebersihan, penjaga hutan, peneliti iklim, & relawan lingkungan, sikap yang tepat:",options:["hanya mengkritik pekerjaan mereka tanpa pernah ikut membantu","menghargai kerja mereka & ikut mendukung upaya yang mereka lakukan","menganggap pekerjaan mereka tidak penting karena hasilnya tidak langsung terlihat oleh masyarakat sekitar"],answer:1,explain:"Menghadapi iklim adalah kerja bersama banyak pihak yang layak diapresiasi & didukung.",hint:"Hargai & dukung pekerjaan mereka."},
{n:77,type:"mcq",micro:"Menyeimbangkan pesan",q:"Cara menyampaikan isu iklim ke teman yang belum peduli tanpa membuatnya menutup diri:",options:["menakut-nakutinya dengan gambaran kiamat supaya ia cepat sadar & langsung mau ikut peduli padamu","menyalahkannya atas semua masalah lingkungan yang terjadi supaya ia merasa bersalah dan mau berubah","mulai dari hal yang ia pedulikan (banjir di kotanya, udara, biaya), tunjukkan solusi, & ajak satu langkah kecil"],answer:2,explain:"Pesan yang terhubung dengan kehidupan orang & menawarkan jalan keluar lebih menggerakkan daripada rasa takut.",hint:"Mulai dari yang ia pedulikan + solusi + langkah kecil."},
{n:78,type:"mcq",micro:"Aksi jangka panjang",q:"Salah satu 'aksi iklim' terpenting yang bisa disiapkan pelajar untuk masa depan:",options:["belajar sungguh-sungguh & mempertimbangkan bidang atau pekerjaan yang ikut membangun solusi (energi, pangan, kota, kebijakan, pendidikan)","tidak perlu memikirkan masa depan sebab nanti ada orang dewasa yang menyelesaikan masalah iklim","memilih bidang atau pekerjaan masa depan hanya berdasarkan gaji paling besar dan nama yang paling bergengsi, tanpa memikirkan apakah pekerjaan itu membantu mengatasi masalah bersama"],answer:0,explain:"Pilihan pendidikan & karier jangka panjang adalah kontribusi besar yang sering terlupakan.",hint:"Belajar & arahkan minat ke solusi."},
{n:79,type:"mcq",micro:"Kolaborasi lintas kelompok",q:"Menghadapi iklim paling berhasil bila...",options:["semua pihak sibuk mencari siapa yang paling bersalah atas masalah ini sebelum bertindak","berbagai kelompok (pelajar, warga, usaha, pemerintah, ilmuwan) bekerja sama, bukan saling menyalahkan","satu kelompok saja yang mengerjakan semuanya sendirian sementara kelompok lain cukup menonton dari jauh"],answer:1,explain:"Masalah sebesar ini butuh kerja sama; menyalahkan tanpa henti menghabiskan energi yang bisa dipakai untuk solusi.",hint:"Kerja sama lintas kelompok."},
{n:80,type:"mcq",micro:"Warga yang menghadapi iklim",q:"Gambaran warga muda yang menghadapi perubahan iklim dengan baik:",options:["panik lalu menyerah karena merasa masalahnya terlalu besar bagi pelajar","menunggu orang lain menyelesaikannya sambil sesekali mengeluh soal cuaca yang makin panas akhir-akhir ini","memahami faktanya, mengubah kebiasaan sebisanya, mengajak orang lain, & mendukung perubahan sistem lewat suaranya"],answer:2,explain:"Menghadapi iklim adalah sikap aktif yang menggabungkan pemahaman, kebiasaan, ajakan, & suara.",hint:"Paham, ubah kebiasaan, ajak, bersuara."},
{n:81,type:"mcq",micro:"Skenario: banjir berulang di lingkungan",q:"Lingkunganmu makin sering banjir saat hujan deras. Aksi warga yang menggabungkan adaptasi & mitigasi:",options:["perbaiki drainase & serapan air, tanam pohon, kurangi sampah ke selokan, & dorong ruang hijau di perencanaan lingkungan","hanya meninggikan lantai rumah masing-masing tanpa mau mencari tahu apa yang menjadi penyebab banjir","pindah ke tempat lain yang lebih tinggi tanpa membenahi lingkungan yang lama ditinggalkan"],answer:0,explain:"Adaptasi (drainase, serapan) & mitigasi (pohon, ruang hijau) sebaiknya berjalan bersama.",hint:"Drainase & serapan + pohon & ruang hijau."},
{n:82,type:"tf",micro:"Suara anak muda didengar",q:"Benar atau Salah: Suara & gerakan pelajar tidak pernah berpengaruh pada keputusan iklim sekolah, kota, atau negara.",answer:false,explain:"Sebaliknya, di banyak tempat gerakan pelajar telah mendorong langkah iklim yang lebih serius, seperti kampanye sekolah bebas plastik & tuntutan energi bersih.",hint:"Suara pelajar sudah mendorong perubahan nyata."},
{n:83,type:"mcq",micro:"Skenario: sekolah menolak usulan",q:"Usulan program iklimmu ditolak sekolah karena dianggap merepotkan. Langkah yang matang:",options:["melanggar aturan sekolah sebagai protes supaya usulanmu diperhatikan oleh semua pihak yang berwenang","tanyakan alasannya, perbaiki usulan agar lebih mudah dijalankan, cari lebih banyak dukungan, & ajukan lagi","menyerah seterusnya karena merasa usulanmu akan ditolak lagi oleh pihak sekolah"],answer:1,explain:"Perubahan sering butuh beberapa kali usaha & usulan yang makin matang.",hint:"Tanya alasan, perbaiki, cari dukungan, ajukan lagi."},
{n:84,type:"mcq",micro:"Skenario: gelombang panas",q:"Saat gelombang panas melanda, tindakan warga yang bijak:",options:["memaksakan semua aktivitas luar ruangan tetap berjalan seperti biasa di siang terik, menyalakan semua AC tanpa memikirkan tetangga yang tidak punya, & tidak peduli pada orang lain","tetap diam di rumah masing-masing tanpa menyapa tetangga, menyerahkan urusan orang lanjut usia kepada keluarganya saja, & menganggap pohon peneduh tidak penting untuk ditanam","saling mengingatkan minum cukup, mengurangi aktivitas berat di siang terik, mengecek tetangga lansia, & mendorong lebih banyak pohon peneduh ke depan"],answer:2,explain:"Adaptasi jangka pendek (saling menjaga) & jangka panjang (penghijauan) sama-sama penting.",hint:"Saling jaga sekarang + pohon peneduh ke depan."},
{n:85,type:"mcq",micro:"Skenario: iklan produk 'hijau'",q:"Sebuah produk mengaku 'ramah iklim' hanya karena kemasannya hijau & bergambar daun. Sikap konsumen kritis:",options:["cari bukti nyata: bahan, cara produksi, & sertifikasi, bukan sekadar tampilan","langsung percaya begitu saja karena kemasannya hijau & ada gambar daun yang tampak ramah lingkungan","mengabaikan semua produk yang mengaku ramah iklim"],answer:0,explain:"Greenwashing memanfaatkan tampilan; keputusan yang baik butuh bukti.",hint:"Cek bukti, bukan tampilan."},
{n:86,type:"mcq",micro:"Skenario: keluarga besar & perjalanan",q:"Keluarga besar biasa berkumpul dengan banyak perjalanan kendaraan pribadi terpisah. Usulan anak yang membantu:",options:["masing-masing keluarga tetap naik kendaraan sendiri-sendiri seperti biasa karena sudah terbiasa begitu","usulkan berangkat bersama dalam kendaraan yang lebih penuh atau bertemu di lokasi yang bisa dijangkau transportasi umum","tidak usah berkumpul supaya tak ada perjalanan tambahan yang menghasilkan emisi gas"],answer:1,explain:"Menggabungkan perjalanan mengurangi emisi tanpa menghilangkan kebersamaan.",hint:"Berangkat bersama / dekat transportasi umum."},
{n:87,type:"mcq",micro:"Skenario: berita iklim yang menakutkan",q:"Kamu membaca berita iklim yang membuatmu sangat cemas semalaman. Cara sehat menyikapinya:",options:["terus membaca berita buruk tentang iklim sepanjang malam sampai kamu merasa semakin cemas & lelah","memutuskan bahwa tidak ada gunanya peduli pada iklim supaya tidak cemas lagi di kemudian hari, lalu mengajak teman melakukan hal yang sama","batasi paparan berita yang menakutkan, cari juga berita tentang solusi, & bicarakan perasaanmu dengan orang dewasa tepercaya"],answer:2,explain:"Menjaga kesehatan mental sambil tetap terinformasi & terlibat adalah keseimbangan yang penting.",hint:"Batasi berita menakutkan + cari solusi + bicarakan."},
{n:88,type:"order",micro:"Menghubungkan aksi lokal & gambaran besar",q:"Urutkan cara kelas menjelaskan mengapa aksi kecil mereka berarti:",items:["Jelaskan masalah besarnya secara sederhana (emisi dari fosil menahan panas)","Tunjukkan bagian yang bisa kelas pengaruhi (energi, sampah, pohon)","Lakukan aksinya & catat hasilnya dalam angka","Hubungkan hasil itu dengan gambaran besar & ajak lebih banyak orang"],answer:[0,1,2,3],explain:"Jelaskan masalah, tunjuk bagian yang bisa dipengaruhi, bertindak & ukur, lalu hubungkan kembali ke gambaran besar.",hint:"Masalah besar dulu, ajak lebih banyak orang terakhir."},
{n:89,type:"mcq",micro:"Skenario: teman menyalahkan negara lain",q:"Teman berkata 'percuma kita berbuat, negara lain penyumbang emisi lebih besar'. Respons yang seimbang:",options:["setiap pihak punya bagian tanggung jawab & manfaatnya; Indonesia pun rentan & punya hutan penting, jadi aksi kita tetap berarti sambil mendorong kerja sama global","setuju dengan temanmu & berhenti peduli, karena kalau negara lain tidak berubah maka usaha kita sia-sia, jadi lebih baik menunggu mereka bertindak lebih dulu daripada kita","hanya terus menyalahkan negara lain tanpa melakukan apa-apa, karena Indonesia tidak punya tanggung jawab & tidak terkena dampak perubahan iklim"],answer:0,explain:"Menunggu pihak lain bergerak lebih dulu adalah taktik penundaan; semua pihak perlu bertindak sesuai perannya.",hint:"Semua punya bagian; aksi kita tetap berarti."},
{n:90,type:"mcq",micro:"Skenario: memilih proyek sekolah",q:"Untuk proyek akhir, kamu bisa memilih tema bebas. Pilihan yang sekaligus jadi aksi iklim:",options:["memilih tema yang tidak kamu pedulikan asalkan tugas selesai tepat waktu dan mudah dikerjakan","meneliti & mengusulkan solusi nyata untuk satu masalah lingkungan di sekolah atau lingkunganmu","menyalin informasi dari internet tanpa menyusun usulan atau gagasan milikmu sendiri"],answer:1,explain:"Tugas sekolah bisa menjadi kesempatan menghasilkan sesuatu yang berguna, bukan sekadar nilai.",hint:"Teliti + usulkan solusi nyata."},
{n:91,type:"mcq",micro:"Skenario: kegiatan bersih pantai/sungai",q:"Ikut kegiatan bersih sungai atau pantai bermanfaat bagi iklim bila juga...",options:["dilakukan sekali lalu dilupakan karena hasilnya tidak bertahan lama dan orang akan membuang lagi","hanya untuk foto yang diunggah ke media sosial sekolah","disertai upaya mengurangi sumber sampah & emisi, bukan hanya membersihkan berulang tanpa mencegah"],answer:2,explain:"Membersihkan itu baik, tetapi mencegah sumbernya membuat dampaknya jangka panjang.",hint:"Bersihkan + cegah sumbernya."},
{n:92,type:"open",micro:"Rencana aksi kelasmu",q:"Rancang satu aksi iklim nyata yang bisa dilakukan kelasmu semester ini. Tulis tujuannya, langkah utamanya, & cara mengukur keberhasilannya.",explain:"Aksi yang punya tujuan jelas, langkah konkret, & cara ukur lebih mungkin berhasil & ditiru.",hint:"Tujuan + langkah + cara mengukur.",sample:"Aksi: 'Kelas Hemat Energi & Hijau'. Tujuan: menurunkan pemakaian listrik kelas & menambah tanaman peneduh. Langkah: satu, tunjuk petugas energi harian yang mengecek lampu, kipas, & proyektor. Dua, pasang pengingat di dekat sakelar. Tiga, tanam & rawat lima pot tanaman di jendela & satu pohon di halaman. Ukuran keberhasilan: bandingkan tagihan/meter listrik kelas sebelum & sesudah tiga bulan, & hitung tanaman yang bertahan hidup. Hasilnya kami bagikan ke kelas lain."},
{n:93,type:"mcq",micro:"Skenario: orang dewasa meremehkan",q:"Seorang dewasa berkata isu iklim 'dibesar-besarkan anak sekarang'. Sikap sopan tapi teguh:",options:["sampaikan dengan hormat bahwa ini didasarkan pada sains & dampaknya sudah dirasakan, lalu tunjukkan contoh nyata di sekitar","langsung membentak agar ia berhenti mengatakan hal yang menurutmu salah, lalu meninggalkan percakapan itu","diam & ikut meremehkan agar tidak dianggap berbeda dari kelompoknya"],answer:0,explain:"Menyampaikan dengan hormat & berbasis fakta lebih membangun daripada bertengkar atau menyerah.",hint:"Sampaikan hormat + berbasis sains + contoh nyata."},
{n:94,type:"tf",micro:"Aksi iklim bagian dari kewargaan",q:"Benar atau Salah: Perubahan iklim murni urusan ilmuwan & pemerintah, & tidak ada kaitannya dengan tanggung jawab kita sebagai warga.",answer:false,explain:"Sebaliknya, iklim menyentuh keadilan, kesehatan, ekonomi, & masa depan bersama, jadi ikut memikirkan & bertindak adalah bagian dari menjadi warga yang bertanggung jawab.",hint:"Aksi iklim = bagian dari kewargaan."},
{n:95,type:"mcq",micro:"Skenario: pilihan kecil setiap hari",q:"Kamu punya banyak pilihan kecil harian (transportasi, makan, beli, buang). Cara memandangnya:",options:["harus sempurna dalam semua pilihan sepanjang waktu atau lebih baik tidak berusaha sejak awal","masing-masing kecil, tetapi arah keseluruhannya membentuk kebiasaan & ikut menandakan pilihan yang kamu dukung","tidak ada pilihan kecil yang berarti sehingga semuanya boleh diabaikan saja tanpa perlu dipikirkan lagi"],answer:1,explain:"Konsistensi arah lebih penting daripada kesempurnaan tiap keputusan.",hint:"Arah keseluruhan lebih penting dari kesempurnaan."},
{n:96,type:"mcq",micro:"Tanda kamu makin siap menghadapi iklim",q:"Tanda sikapmu berkembang:",options:["kamu makin panik setiap mendengar berita iklim & memilih menghindari topiknya agar tidak merasa cemas","kamu terus menyalahkan dirimu atas semua masalah tanpa melakukan tindakan nyata","kamu memahami sebab & dampaknya, punya beberapa kebiasaan aksi, & berani membicarakannya dengan tenang & berbasis fakta"],answer:2,explain:"Pertumbuhan tampak dari pemahaman, kebiasaan, & kemampuan menyuarakan dengan tenang.",hint:"Paham, punya kebiasaan aksi, berani bicara."},
{n:97,type:"mcq",micro:"Kebiasaan aksi iklim",q:"Manakah kumpulan kebiasaan menghadapi iklim yang baik?",options:["hemat energi, transportasi rendah emisi, kurangi makanan & barang terbuang, jaga & tanam pohon, bicarakan & dukung kebijakan baik","mengabaikan sumber listrik, boros memakai barang, membuang makanan, & diam saja saat ada peluang bersuara","menunggu solusi ajaib datang dari orang lain sambil sendiri tidak berbuat apa-apa dalam kehidupan sehari-hari"],answer:0,explain:"Kebiasaan di beberapa bidang, ditambah menyuarakan perubahan sistem, membentuk aksi iklim yang utuh.",hint:"Hemat energi, transport bersih, kurangi limbah, pohon, bersuara."},
{n:98,type:"mcq",micro:"Saat ragu apa yang harus dilakukan",q:"Aturan sederhana saat bingung mulai dari mana menghadapi iklim:",options:["coba ubah semuanya sekaligus dalam satu minggu lalu akhirnya kelelahan dan berhenti total tanpa hasil","pilih satu bidang yang paling bisa kamu pengaruhi sekarang, lakukan satu langkah nyata, & ajak satu orang lain","tunggu sampai kamu tahu segala hal tentang iklim baru kemudian mulai bertindak dengan penuh keyakinan"],answer:1,explain:"Memulai dari satu langkah yang nyata & mengajak orang lain menjaga aksi tetap berjalan.",hint:"Satu bidang, satu langkah, satu ajakan."},
{n:99,type:"mcq",micro:"Mengajari yang lebih muda",q:"Cara membantu adik memahami perubahan iklim tanpa membuatnya takut:",options:["menakut-nakutinya dengan cerita kiamat, menyuruhnya patuh tanpa penjelasan, & melarangnya bertanya lagi soal lingkungan","menyembunyikan berita tentang iklim darinya, berpura-pura tidak ada masalah, & menjawab 'nanti juga kamu tahu sendiri' setiap ia bertanya","jelaskan sederhana dengan contoh sehari-hari, tekankan bahwa banyak orang sedang mencari solusi, & ajak melakukan aksi kecil bersama"],answer:2,explain:"Anak belajar peduli lewat pemahaman yang jujur, harapan yang nyata, & tindakan bersama.",hint:"Sederhana + tekankan solusi + aksi kecil bersama."},
{n:100,type:"mcq",micro:"Sintesis",q:"Inti dari 'Perubahan Iklim & Aksi Nyata' adalah...",options:["perubahan iklim nyata & terutama disebabkan manusia, dampaknya sudah terasa termasuk di Indonesia, & menghadapinya menuntut mengurangi emisi serta beradaptasi, lewat kebiasaan pribadi sekaligus perubahan sistem, dengan sikap yang berbasis fakta, adil, & penuh harapan aktif","perubahan iklim hanyalah siklus alam yang tidak ada hubungannya dengan manusia, dampaknya belum terasa di Indonesia, sehingga cukup menunggu pemerintah dan teknologi baru tanpa perlu mengurangi emisi atau beradaptasi sendiri, sambil terus menyalahkan pihak lain","perubahan iklim itu nyata tetapi terlalu besar dan rumit untuk dihadapi, jadi warga biasa dan pelajar tidak bisa berbuat apa-apa selain pasrah sepanjang waktu, sambil saling menyalahkan negara atau kelompok lain"],answer:0,explain:"Memahami sebab & dampak, bertindak di tingkat pribadi & sistem, menuntut keadilan, & memilih harapan yang aktif, itulah menghadapi iklim sebagai warga.",hint:"Nyata & ulah manusia + kurangi emisi & adaptasi + pribadi & sistem + adil & penuh harapan."},
];
